/** Reproducible, locally served browser bytes. The published console never imports a bundler or browser package. */
import { build } from "esbuild";
import { readFileSync, writeFileSync, existsSync, readdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join, resolve } from "node:path";
import { createRequire } from "node:module";

const require = createRequire(new URL("../../admin/package.json", import.meta.url));
export async function timelineAssets() {
  const result = await build({ entryPoints: [fileURLToPath(new URL("../../admin/src/console/timeline-client.mjs", import.meta.url))], bundle: true, write: false, platform: "browser", format: "iife", target: ["chrome100", "firefox100", "safari16.4"], minify: true, legalComments: "inline", logLevel: "silent", metafile: true, absWorkingDir: fileURLToPath(new URL("../../", import.meta.url)) });
  const roots = new Set();
  for (const input of Object.keys(result.metafile.inputs).filter(p => p.includes("node_modules/"))) {
    let folder = dirname(resolve(fileURLToPath(new URL("../../", import.meta.url)), input));
    while (!existsSync(join(folder, "package.json"))) {
      const parent = dirname(folder); if (parent === folder) throw new Error("No package for " + input); folder = parent;
    }
    roots.add(folder);
  }
  const notices = [...roots].sort().map(folder => {
    const pkg = JSON.parse(readFileSync(join(folder, "package.json"), "utf8"));
    const files = readdirSync(folder);
    const license = files.find(f => /^license[-.]mit/i.test(f)) ?? files.find(f => /^license(?:\.md|\.txt)?$/i.test(f));
    if (!license) throw new Error("Missing bundled license for " + pkg.name);
    return "/*! " + pkg.name + " " + pkg.version + "\n" + readFileSync(join(folder, license), "utf8").replace(/\*\//g, "* /") + "\n*/\n";
  }).join("");
  return { script: result.outputFiles[0].text + notices, css: readFileSync(require.resolve("vis-timeline/styles/vis-timeline-graph2d.min.css"), "utf8") };
}
export async function generatedTimelineAssets() {
  const { script, css } = await timelineAssets();
  return "// Generated by .github/scripts/timeline-assets.mjs --write. Edit timeline-client.mjs, never these bytes.\n" +
    "export const TIMELINE_SCRIPT = " + JSON.stringify(script) + ";\nexport const TIMELINE_CSS = " + JSON.stringify(css) + ";\n";
}
if (process.argv.includes("--write")) writeFileSync(new URL("../../admin/src/console/timeline-assets.generated.mjs", import.meta.url), await generatedTimelineAssets());
